/** Actual immutable builder/interface preflight; all generated bytes stay in memory. */
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {modes,expectedWaitQuery} from './check-receipt.mjs';
const source=new URL('../../../',import.meta.url);
const sha=b=>createHash('sha256').update(b).digest('hex');
const read=p=>readFileSync(new URL(p,source));
const {buildG2ProfileCandidate}=await import(new URL('tools/website-tracking/tracking-system/build-g2-profile-candidate.mjs',source));
const result=buildG2ProfileCandidate(read('docs/audit/INSTALLED_SOURCE_COMPARISON_2026-11-07.json'));
const store=Buffer.from(result.files.find(v=>v.path==='includes/g2-profile/purpose-store.php').content_base64,'base64').toString('utf8');
for(const declaration of ['public function choose(string $subject, array $flags, string $notice, int $now, bool $uncertain = false): array','public function stage(array $capture): array','private function transaction(callable $work)'])assert.ok(store.includes(declaration),declaration);
assert.ok(store.includes('INSERT IGNORE INTO {$this->state} '));
for(const mode of modes){
 const table='g37_pref_'+sha('g38|'+mode).slice(0,12)+'_synthetic_bsre_consent_state';
 const subject='aa'+sha('SYNTHETIC_G38_'+mode).slice(0,62);
 const sourceQuery=mode.startsWith('choose_')?store.match(/"(INSERT IGNORE INTO \{\$this->state\} [^"]+)"/)[1]:store.match(/"(SELECT \* FROM \{\$this->state\} WHERE subject_key=%s FOR UPDATE)"/)[1];
 assert.equal(sourceQuery.replace('{$this->state}',table).replace('%s',"'"+subject+"'"),expectedWaitQuery(mode));
}
assert.ok(store.indexOf("Consent evidence retired.")<store.indexOf('INSERT IGNORE INTO {$this->captures}'));
const dir='tools/website-tracking/g5-preference-runtime/';
const {buildManifest,names}=await import(new URL(dir+'build-runtime.mjs',source));
const manifest=buildManifest();assert.equal(names.length,5);
const runtime=read(dir+'candidate/plugin/includes/candidate/retention/ActualPreferenceRetention.php').toString('utf8');
for(const method of ['public static function bind(','public function initialize(string $nonce): array','public function preview(array $subjects,string $nonce): array','public function apply(array $plan,string $nonce): array'])assert.ok(runtime.includes(method),method);
const atomic=read(dir+'candidate/plugin/includes/candidate/retention/PreferenceAtomicStore.php').toString('utf8');
const mutate=atomic.slice(atomic.indexOf('public function mutate('),atomic.indexOf('private function commit('));
assert.ok(mutate.indexOf('$result=$work(')<mutate.indexOf('$this->writePending('));
assert.ok(runtime.includes('$deleted=$this->store->deleteExact('));
assert.ok(atomic.includes('$body=$this->custody->seal('));
const fixtures=read(dir+'native/FixturePorts.php').toString('utf8');
for(const marker of ['public ?\\Closure $onCoverage=null;','G37_INJECTED_KEY_FAILURE',"$this->keys->failSeal=true;"])assert.ok(fixtures.includes(marker),marker);
process.stdout.write(JSON.stringify({status:'PASS',real_g2_builder:result.profile,generated_store_sha256:sha(store),runtime_manifest_sha256:manifest.sha256,runtime_files:names.length,native_execution:false})+'\n');
